mapper.select:
select id, house_id, rabbit_id, cage_id, departure_type, departure_date, reason, remark, request_id, create_by, create_time, update_by, operator_name, update_time
from rabbit_departure_records
where house_id = #{houseId} and rabbit_id = #{rabbitId}
order by id desc
limit #{limit}

select id, house_id, rabbit_id, cage_id, departure_type, departure_date, reason, remark, request_id, create_by, create_time, update_by, operator_name, update_time
from rabbit_departure_records
where house_id = #{houseId}

    and rabbit_id = #{rabbitId}


    and departure_date >= #{from}


    and departure_date <= #{to}

order by departure_date desc, id desc
limit #{limit} offset #{offset}
